import{_ as t,o,c as a,a2 as r}from"./chunks/framework.u0XqMXcb.js";const u=JSON.parse('{"title":"Hardware requirements","description":"","frontmatter":{"title":"Hardware requirements"},"headers":[],"relativePath":"docs/overview/hardware-requirements.md","filePath":"docs/overview/hardware-requirements.md","lastUpdated":1790281380000}'),n={name:"docs/overview/hardware-requirements.md"};function s(i,e,d,l,m,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="hardware-requirements" tabindex="-1">Hardware requirements <a class="header-anchor" href="#hardware-requirements" aria-label="Permalink to &quot;Hardware requirements&quot;">​</a></h1><p>These requirements are only for running a <strong>local</strong> builtin model — the whole point of which is to work fully offline with nothing leaving your machine.</p><h2 id="dedicated-vram-vs-unified-memory" tabindex="-1">Dedicated VRAM vs. unified memory <a class="header-anchor" href="#dedicated-vram-vs-unified-memory" aria-label="Permalink to &quot;Dedicated VRAM vs. unified memory&quot;">​</a></h2><p>OrbySystems sizes its local model against whichever kind of memory your machine actually has available for it:</p><ul><li><strong>Dedicated VRAM</strong> — a discrete GPU (most Windows/Linux gaming and workstation cards). OrbySystems targets your GPU&#39;s <em>free</em> VRAM.</li><li><strong>Unified memory</strong> — Apple silicon Macs, and machines without a discrete GPU. OrbySystems targets your machine&#39;s <em>free</em> system RAM, since there&#39;s no separate VRAM pool.</li></ul><p>Either way, OrbySystems detects this automatically and recommends a model size that comfortably fits — you don&#39;t need to work out the numbers below yourself. They&#39;re here so you know what to expect before you install OrbySystems.</p><h2 id="recommended-the-4b-model-at-64k-context" tabindex="-1">Recommended: the 4B model at 64k context <a class="header-anchor" href="#recommended-the-4b-model-at-64k-context" aria-label="Permalink to &quot;Recommended: the 4B model at 64k context&quot;">​</a></h2><p>The 4B model at a 64k-token context window is the sweet spot OrbySystems is tuned around — capable enough for real finance reasoning over a long conversation, while still running comfortably on a single consumer GPU or an ordinary laptop&#39;s unified memory.</p><table tabindex="0"><thead><tr><th></th><th>Dedicated VRAM</th><th>Unified memory (system RAM)</th></tr></thead><tbody><tr><td>Model weights + context</td><td>~6 GB</td><td>~6 GB</td></tr><tr><td>Recommended headroom</td><td>~2 GB</td><td>~2 GB or more</td></tr><tr><td><strong>Target free memory</strong></td><td><strong>~8 GB</strong></td><td><strong>~8 GB</strong></td></tr><tr><td><strong>Recommended installed memory</strong></td><td><strong>10-12 GB VRAM card</strong></td><td><strong>16 GB total system RAM</strong></td></tr></tbody></table><p>The &quot;target free memory&quot; row is what is recommended to be <em>available</em> for the model — the last row estimates what the installed memory should be taking into account reasonable overheads. These numbers can change depending upon what else is running on your system and what context size you choose.</p><p><em>Hint</em>: Go to the <a href="./../settings/models">Settings -&gt; Models</a> page when OrbySystems first starts, it will tell you what GPU/unified device it detects and how much free memory it sees.</p><p>The Settings -&gt; Models page will also indicate how much context has been allocated based on the free memory. This can be adjusted via low/medium/high settings on the model card.</p><h2 id="the-2b-model-supported-not-recommended" tabindex="-1">The 2B model: supported, not recommended <a class="header-anchor" href="#the-2b-model-supported-not-recommended" aria-label="Permalink to &quot;The 2B model: supported, not recommended&quot;">​</a></h2><p>OrbySystems also ships a 2B model. It&#39;s supported and will run on much lighter hardware (roughly 4-6 GB of free memory), which makes it a reasonable fallback on an older machine or a memory-constrained VM. It&#39;s meaningfully less capable than the 4B model at real finance reasoning, though, so it isn&#39;t what OrbySystems recommends by default — treat it as a &quot;this still works&quot; option rather than a target to design around.</p><h2 id="docling-document-ingestion" tabindex="-1">Docling (document ingestion) <a class="header-anchor" href="#docling-document-ingestion" aria-label="Permalink to &quot;Docling (document ingestion)&quot;">​</a></h2><p>Docling is the local service OrbySystems uses to convert PDFs and other documents into text for ingestion (and to re-read a page&#39;s layout when redacting it — see the <a href="/OrbySystems-Finance/docs/tools/pii-redactor">PII Redactor</a>). It&#39;s deliberately <strong>CPU-only</strong>: on a GPU, its layout/OCR models use a lot of VRAM — worst on image-heavy pages — for little wall-clock gain over CPU, and that VRAM is worth more to your local model. So Docling adds no VRAM requirement, but it does need roughly <strong>4 GB of free system RAM</strong> while it&#39;s running, on top of whatever your local model needs.</p><h2 id="presidio-pii-detection" tabindex="-1">Presidio (PII detection) <a class="header-anchor" href="#presidio-pii-detection" aria-label="Permalink to &quot;Presidio (PII detection)&quot;">​</a></h2><p>Presidio is OrbySystems&#39;s default engine for detecting personal information — used by the <a href="/OrbySystems-Finance/docs/tools/pii-detector">PII Detector</a> and <a href="/OrbySystems-Finance/docs/tools/pii-redactor">PII Redactor</a>. It&#39;s also <strong>CPU-only</strong>, and needs roughly <strong>1.5 GB of free system RAM</strong> while running.</p><h2 id="adding-it-up" tabindex="-1">Adding it up <a class="header-anchor" href="#adding-it-up" aria-label="Permalink to &quot;Adding it up&quot;">​</a></h2><p>Docling and Presidio are both started on demand — they only run (and only use this memory) while you&#39;re actually ingesting a document or checking/redacting PII, not for the whole time OrbySystems is open. If you do that alongside chatting with your local model, budget their memory on top of the model&#39;s: roughly <strong>+4 GB of system RAM while Docling is active</strong>, and <strong>+1.5 GB of system RAM while Presidio is active</strong> — both independent of whether your model itself runs on a dedicated GPU or unified memory, since these two always run on CPU/RAM regardless.</p><h2 id="if-your-hardware-falls-short" tabindex="-1">If your hardware falls short <a class="header-anchor" href="#if-your-hardware-falls-short" aria-label="Permalink to &quot;If your hardware falls short&quot;">​</a></h2><p>Nothing about OrbySystems requires a local model - you can connect to an external model running in the cloud or on a separate machine via a standard API endpoint instead (see <a href="/OrbySystems-Finance/docs/settings/models">Settings → Models</a>). However, OrbySystems operates under the assumption that there is at least one <strong>trusted</strong> model configured that can be used to chat about your data. Be clear about which LLM services you trust.</p>',22)])])}const y=t(n,[["render",s]]);export{u as __pageData,y as default};
